        in.nextToken();
        int n = (int) in.nval;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (int) in.nval;
        }
        int k = removeDuplicates(a);
        StringBuilder sb = new StringBuilder();
        sb.append(k).append("\n");
        for (int i = 0; i < k; i++) sb.append(a[i]).append(i + 1 < k ? " " : "");
        System.out.println(sb);
    }
